1	import React, {
2	  useState,
3	  useEffect,
4	  useMemo,
5	  useRef,
6	  useCallback,
7	  forwardRef,
8	  useImperativeHandle,
9	} from "react";
10	import { createPortal } from "react-dom";
11	import Image from "@/components/AppImage";
12	import { mockThumbnailMapping } from "@/utils/mockDataMapping";
13	import Tooltip from "@/components/Tooltip";
14	
15	// 時間單位換算: 總秒數 -> hh:mm:ss 或 mm:ss
16	function formatTime(seconds: number): string {
17	  if (!Number.isFinite(seconds) || seconds < 0) return "0:00";
18	  const total = Math.floor(seconds);
19	  const h = Math.floor(total / 3600);
20	  const m = Math.floor((total % 3600) / 60);
21	  const s = total % 60;
22	  if (h > 0) {
23	    return `${h}:${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`; // hh:mm:ss
24	  }
25	  return `${m}:${s.toString().padStart(2, "0")}`; // mm:ss
26	}
27	
28	// 與分析圖同步：播放、拖曳進度、鍵盤 seek 時回報目前秒數
29	const THUMB_INTERVAL_SEC = 360;
30	
31	const RIGHT_MARGIN = 28; // 與 EngagementChart 同步
32	
33	// 截圖尚未生成時，以藍色漸層色塊代替影格
34	const PLACEHOLDER_COLORS = [
35	  "bg-blue-10",
36	  "bg-blue-20",
37	  "bg-blue-30",
38	  "bg-blue-40",
39	  "bg-blue-50",
40	  "bg-blue-60",
41	  "bg-blue-70",
42	  "bg-blue-80",
43	  "bg-blue-90",
44	  "bg-blue-100",
45	];
46	
47	export type VideoPlayerHandle = {
48	  seek: (seconds: number) => void;
49	};
50	
51	type VideoPlayerProps = {
52	  videoSrc?: string;
53	  onPlaybackTime?: (seconds: number) => void;
54	  chartHighlightSeconds?: number | null;
55	  pxPerMinute?: number;
56	  progressFraction: number;
57	  plotboxWidth: number;
58	  syncScrollRef?: React.RefObject<HTMLDivElement | null>;
59	  previewContainer?: HTMLElement | null;
60	  maxDuration: number;
61	  lessonId: string;
62	  status: string;
63	};
64	
65	const VideoPlayer = forwardRef<VideoPlayerHandle, VideoPlayerProps>(
66	  function VideoPlayer(
67	    {
68	      videoSrc,
69	      onPlaybackTime,
70	      chartHighlightSeconds,
71	      pxPerMinute,
72	      progressFraction,
73	      plotboxWidth,
74	      syncScrollRef,
75	      previewContainer,
76	      maxDuration,
77	      lessonId,
78	      status,
79	    },
80	    ref,
81	  ) {
82	    const [thumbnails, setThumbnails] = useState<string[]>([]);
83	    const [currentTime, setCurrentTime] = useState(0);
84	    const [duration, setDuration] = useState(0);
85	    const [isPlaying, setIsPlaying] = useState(false);
86	    const [volume, setVolume] = useState(1);
87	    const [isMuted, setIsMuted] = useState(false);
88	    const [playbackRate, setPlaybackRate] = useState(1.0);
89	    const videoRef = useRef<HTMLVideoElement>(null);
90	    const progressBarRef = useRef<HTMLDivElement>(null);
91	    const keyframeStripRef = useRef<HTMLDivElement>(null);
92	    const isFetchingThumbnailsRef = useRef(false);
93	    const isScrubbingRef = useRef(false);
94	    const [scrubTime, setScrubTime] = useState<number | null>(null);
95	    const [isThumbHovered, setIsThumbHovered] = useState(false);
96	    const [videoLoadFailed, setVideoLoadFailed] = useState(false);
97	    const [thumbnailFetchSettled, setThumbnailFetchSettled] = useState(false);
98	    const yAxisGutterPx = 0; // Align with Recharts plot area (yAxisWidth)
99	
100	    useEffect(() => {
101	      setVideoLoadFailed(false);
102	      setThumbnailFetchSettled(false);
103	    }, [videoSrc]);
104	
105	    // analyzing = 已有分析資料但截圖還沒生成，用藍色漸層色塊代替
106	    const hasVideoSource = Boolean(videoSrc) && !videoLoadFailed;
107	    const showPlaceholderStrip =
108	      status === "analyzing" &&
109	      thumbnails.length === 0 &&
110	      (!hasVideoSource || thumbnailFetchSettled);
111	
112	    const emitPlaybackTime = useCallback(
113	      (t: number) => {
114	        onPlaybackTime?.(t);
115	      },
116	      [onPlaybackTime],
117	    );
118	
119	    // 沒有影片時改用 metadata 的 duration 當時間軸
120	    const getTimelineLimit = useCallback(() => {
121	      const videoDuration = videoRef.current?.duration ?? NaN;
122	      const hasMedia = Number.isFinite(videoDuration) && videoDuration > 0;
123	      if (!hasMedia && !showPlaceholderStrip) return 0;
124	      if (maxDuration && maxDuration > 0) return maxDuration;
125	      return hasMedia ? videoDuration : 0;
126	    }, [maxDuration, showPlaceholderStrip]);
127	
128	    const seekTo = useCallback(
129	      (seconds: number) => {
130	        const limit = getTimelineLimit();
131	        if (limit <= 0) return;
132	
133	        const video = videoRef.current;
134	        const hasMedia =
135	          !!video && Number.isFinite(video.duration) && video.duration > 0;
136	        // 把秒數限制在 [0, limit] 之間
137	        const clamped = Math.min(
138	          Math.max(0, seconds),
139	          hasMedia ? Math.min(limit, video.duration) : limit,
140	        );
141	
142	        if (hasMedia) video.currentTime = clamped;
143	        setCurrentTime(clamped);
144	        setScrubTime(null);
145	        emitPlaybackTime(clamped);
146	      },
147	      [emitPlaybackTime, getTimelineLimit],
148	    );
149	
150	    useImperativeHandle(
151	      ref,
152	      () => ({
153	        seek: seekTo,
154	      }),
155	      [seekTo],
156	    );
157	
158	    const fetchThumbnails = async (videoDuration: number) => {
159	      if (isFetchingThumbnailsRef.current) return;
160	      isFetchingThumbnailsRef.current = true;
161	
162	      const interval = THUMB_INTERVAL_SEC;
163	      try {
164	        const promises = [];
165	        const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
166	
167	        for (let i = 0; i < videoDuration; i += interval) {
168	          const minuteIndex = Math.floor(i / 60) + 1;
169	          const url = `${basePath}/api/image/thumb/${lessonId}/${minuteIndex}`;
170	          promises.push(
171	            fetch(url, { method: "GET", headers: { accept: "*/*" } })
172	              .then((res) => {
173	                if (!res.ok) {
174	                  throw new Error(
175	                    `Thumb ${minuteIndex} response was not ok (Status: ${res.status})`,
176	                  );
177	                }
178	                return res.blob();
179	              })
180	              .then((blob) => URL.createObjectURL(blob)),
181	          );
182	        }
183	        const resolvedThumbs = await Promise.all(promises);
184	        setThumbnails(resolvedThumbs);
185	        console.log("Fetched thumbnails from API");
186	      } catch (error: any) {
187	        console.error("Error fetching thumbnails:", error);
188	        const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
189	        const mockThumbnailPath =
190	          mockThumbnailMapping[lessonId as keyof typeof mockThumbnailMapping];
191	
192	        if (mockThumbnailPath) {
193	          const totalCount = Math.floor(videoDuration / interval) + 1;
194	          const dynamicThumbnails = Array.from(
195	            { length: totalCount },
196	            (_, index) => {
197	              const currentSeconds = index * interval;
198	              const fileNumber = String(index + 1).padStart(3, "0");
199	              return `${basePath}${mockThumbnailPath}/shot_${fileNumber}_${currentSeconds}s.jpg`;
200	            },
201	          );
202	          setThumbnails(dynamicThumbnails);
203	          console.log("Using mock thumbnails for lessonId:", lessonId);
204	        } else {
205	          console.error(`No mock thumbnails found for lessonId: ${lessonId}`);
206	        }
207	      } finally {
208	        isFetchingThumbnailsRef.current = false;
209	        setThumbnailFetchSettled(true);
210	      }
211	    };
212	
213	    // 當影片 Metadata 載入完成，取得正確的 duration 後再開始向 API 要圖片
214	    const handleLoadedMetadata = useCallback(() => {
215	      const video = videoRef.current;
216	      if (!video) return;
217	
218	      const duration = video.duration;
219	      setDuration(duration);
220	
221	      const time = video.currentTime;
222	      setCurrentTime(time);
223	      emitPlaybackTime(time);
224	
225	      if (duration > 0) {
226	        fetchThumbnails(duration);
227	      }
228	    }, [emitPlaybackTime, duration]);
229	
230	    // 重新載入時釋放記憶體避免 Memory Leak
231	    useEffect(() => {
232	      return () => {
233	        thumbnails.forEach((url) => {
234	          if (url.startsWith("blob:")) {
235	            URL.revokeObjectURL(url);
236	          }
237	        });
238	      };
239	    }, [thumbnails]);
240	
241	    const handleTimeUpdate = useCallback(() => {
242	      const video = videoRef.current;
243	      if (!video || isScrubbingRef.current) return;
244	      // const t = video.currentTime;
245	
246	      let t = video.currentTime;
247	      const limit =
248	        maxDuration && maxDuration > 0 ? maxDuration : video.duration;
249	      if (t >= limit) {
250	        t = limit;
251	        video.currentTime = limit;
252	        video.pause(); // 自動暫停
253	        setIsPlaying(false);
254	      }
255	
256	      setCurrentTime(t);
257	      emitPlaybackTime(t);
258	    }, [emitPlaybackTime]);
259	
260	    useEffect(() => {
261	      const video = videoRef.current;
262	      if (!video) return;
263	      video.addEventListener("timeupdate", handleTimeUpdate);
264	      return () => video.removeEventListener("timeupdate", handleTimeUpdate);
265	    }, [handleTimeUpdate]);
266	
267	    const togglePlay = () => {
268	      const video = videoRef.current;
269	      if (!video) return;
270	      if (video.paused) void video.play();
271	      else video.pause();
272	    };
273	
274	    const toggleMute = () => setIsMuted((v) => !v);
275	
276	    const onVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
277	      const next = Number(e.target.value);
278	      const clamped = Math.min(1, Math.max(0, next));
279	      setVolume(clamped);
280	      if (clamped > 0) setIsMuted(false);
281	    };
282	
283	    useEffect(() => {
284	      const video = videoRef.current;
285	      if (!video) return;
286	      video.playbackRate = playbackRate;
287	    }, [playbackRate]);
288	
289	    const onSpeedChange = (e: React.ChangeEvent<HTMLInputElement>) => {
290	      setPlaybackRate(Number(e.target.value));
291	    };
292	
293	    const getTimeFromPointerClientX = useCallback(
294	      (clientX: number) => {
295	        const el = progressBarRef.current;
296	        const limit = getTimelineLimit();
297	        if (!el || limit <= 0) return 0;
298	
299	        const rect = el.getBoundingClientRect();
300	        if (rect.width <= 0) return 0;
301	
302	        const ratio = (clientX - rect.left) / rect.width;
303	        return Math.min(limit, Math.max(0, ratio * limit));
304	      },
305	      [getTimelineLimit],
306	    );
307	
308	    // 確保游標、playbar、progressLine 對齊
309	    const onKeyframePointerDown = useCallback(
310	      (e: React.PointerEvent<HTMLDivElement>) => {
311	        if (e.pointerType === "mouse" && e.button !== 0) return;
312	        if (getTimelineLimit() <= 0) return;
313	        e.preventDefault();
314	        const t = getTimeFromPointerClientX(e.clientX);
315	        seekTo(t);
316	      },
317	      [getTimelineLimit, getTimeFromPointerClientX, seekTo],
318	    );
319	
320	    const endScrub = useCallback(
321	      (e: React.PointerEvent<HTMLDivElement>) => {
322	        if (!isScrubbingRef.current) return;
323	        isScrubbingRef.current = false;
324	        const bar = progressBarRef.current;
325	        if (bar?.hasPointerCapture(e.pointerId)) {
326	          bar.releasePointerCapture(e.pointerId);
327	        }
328	        const video = videoRef.current;
329	        const hasMedia =
330	          !!video && Number.isFinite(video.duration) && video.duration > 0;
331	        const t = hasMedia ? video.currentTime : (scrubTime ?? currentTime);
332	        setScrubTime(null);
333	        setCurrentTime(t);
334	        emitPlaybackTime(t);
335	      },
336	      [emitPlaybackTime, scrubTime, currentTime],
337	    );
338	
339	    const onProgressPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
340	      if (e.pointerType === "mouse" && e.button !== 0) return;
341	      if (getTimelineLimit() <= 0) return;
342	      e.preventDefault();
343	      e.currentTarget.setPointerCapture(e.pointerId);
344	      isScrubbingRef.current = true;
345	      const t = getTimeFromPointerClientX(e.clientX);
346	      const video = videoRef.current;
347	      if (video && Number.isFinite(video.duration)) video.currentTime = t;
348	      setScrubTime(t);
349	      setCurrentTime(t);
350	      emitPlaybackTime(t);
351	    };
352	
353	    const onProgressPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
354	      if (!isScrubbingRef.current) return;
355	      const t = getTimeFromPointerClientX(e.clientX);
356	      const video = videoRef.current;
357	      if (video && Number.isFinite(video.duration)) video.currentTime = t;
358	      setScrubTime(t);
359	      emitPlaybackTime(t);
360	    };
361	
362	    const onProgressKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
363	      const limit = getTimelineLimit();
364	      if (limit <= 0) return;
365	      const video = videoRef.current;
366	      const hasMedia =
367	        !!video && Number.isFinite(video.duration) && video.duration > 0;
368	      const step = 5;
369	      let t = hasMedia ? video.currentTime : (scrubTime ?? currentTime);
370	      let handled = false;
371	      if (e.key === "ArrowLeft") {
372	        t = Math.max(0, t - step);
373	        handled = true;
374	      } else if (e.key === "ArrowRight") {
375	        t = Math.min(limit, t + step);
376	        handled = true;
377	      } else if (e.key === "Home") {
378	        t = 0;
379	        handled = true;
380	      } else if (e.key === "End") {
381	        t = limit;
382	        handled = true;
383	      }
384	      if (handled) {
385	        e.preventDefault();
386	        if (hasMedia) video.currentTime = t;
387	        setCurrentTime(t);
388	        emitPlaybackTime(t);
389	      }
390	    };
391	
392	    useEffect(() => {
393	      const video = videoRef.current;
394	      if (!video) return;
395	      video.volume = volume;
396	      video.muted = isMuted || volume === 0;
397	    }, [volume, isMuted]);
398	
399	    const displayTime = scrubTime ?? currentTime;
400	    const stripHighlightSeconds =
401	      chartHighlightSeconds != null &&
402	      Number.isFinite(chartHighlightSeconds) &&
403	      chartHighlightSeconds >= 0
404	        ? chartHighlightSeconds
405	        : displayTime;
406	
407	    const progressPct = progressFraction * 100;
408	    const isThumbPressed = scrubTime !== null;
409	    const isThumbEnlarged = isThumbHovered && !isThumbPressed;
410	
411	    const activeThumbIndex =
412	      thumbnails.length > 0
413	        ? Math.min(
414	            thumbnails.length - 1,
415	            Math.floor(stripHighlightSeconds / THUMB_INTERVAL_SEC),
416	          )
417	        : -1;
418	
419	    const totalChartWidth = plotboxWidth;
420	    const totalThumbs = thumbnails.length; // 總張數 N
421	
422	    // 高度固定為 h-[132px]， 16:9 寬高比計算寬度
423	    const activeThumbWidthPx = 132 * (16 / 9);
424	
425	    // Non-active Thumbnail 寬度 = (總寬 - Active) / (N - 1)
426	    const nonActiveThumbWidthPx =
427	      totalThumbs > 1
428	        ? (totalChartWidth - activeThumbWidthPx) / (totalThumbs - 1)
429	        : 0;
430	
431	    useEffect(() => {
432	      const master = syncScrollRef?.current;
433	      const slave = keyframeStripRef.current;
434	      if (!master || !slave) return;
435	
436	      const onScroll = () => {
437	        requestAnimationFrame(() => {
438	          slave.scrollLeft = master.scrollLeft;
439	        });
440	      };
441	
442	      slave.scrollLeft = master.scrollLeft;
443	
444	      master.addEventListener("scroll", onScroll, { passive: true });
445	      return () => master.removeEventListener("scroll", onScroll);
446	    }, [syncScrollRef]);
447	
448	    // 每 6 分鐘一格，色階循環使用
449	    const placeholderTiles = useMemo(() => {
450	      if (!showPlaceholderStrip) return [];
451	      const total = maxDuration && maxDuration > 0 ? maxDuration : duration;
452	      const count =
453	        total > 0
454	          ? Math.max(1, Math.ceil(total / THUMB_INTERVAL_SEC))
455	          : PLACEHOLDER_COLORS.length;
456	
457	      return Array.from(
458	        { length: count },
459	        (_, i) => PLACEHOLDER_COLORS[i % PLACEHOLDER_COLORS.length],
460	      );
461	    }, [showPlaceholderStrip, maxDuration, duration]);
462	
463	    const activePlaceholderIndex =
464	      placeholderTiles.length > 0
465	        ? Math.min(
466	            placeholderTiles.length - 1,
467	            Math.floor(stripHighlightSeconds / THUMB_INTERVAL_SEC),
468	          )
469	        : -1;
470	
471	    // Non-active 色塊寬度 = (總寬 - Active) / (N - 1)
472	    const placeholderTileWidthPx =
473	      placeholderTiles.length > 1
474	        ? (totalChartWidth - activeThumbWidthPx) / (placeholderTiles.length - 1)
475	        : 0;
476	
477	    useEffect(() => {
478	      const master = syncScrollRef?.current;
479	      const slave = keyframeStripRef.current;
480	      if (!master || !slave) return;
481	
482	      const onScroll = () => {
483	        slave.scrollLeft = master.scrollLeft;
484	      };
485	
486	      master.addEventListener("scroll", onScroll, { passive: true });
487	      return () => master.removeEventListener("scroll", onScroll);
488	    }, [syncScrollRef]);
489	
490	    const activeThumbSrc =
491	      activeThumbIndex >= 0 ? thumbnails[activeThumbIndex] : null;
492	
493	    // 沒有影片可播放時，播放相關控制項一律停用
494	    const mediaControlsDisabled = showPlaceholderStrip;
495	
496	    const previewContent = showPlaceholderStrip ? (
497	      <div
498	        className={`h-full w-full rounded-[4px] ${
499	          placeholderTiles[Math.max(activePlaceholderIndex, 0)] ??
500	          PLACEHOLDER_COLORS[0]
501	        }`}
502	      />
503	    ) : activeThumbSrc ? (
504	      <img
505	        src={activeThumbSrc}
506	        alt="active-keyframe"
507	        className="h-full w-full object-cover object-center rounded-[4px]"
508	      />
509	    ) : null;
510	
511	    // 尚未開始上課時沒有錄播檔，只顯示提示文字
512	    if (status === "pending") {
513	      return (
514	        <section className="h-[214px] bg-[rgba(6,45,65,0.1)] rounded-[12px] flex items-center justify-center">
515	          <p className="body-2-reg text-gray-70">尚無錄播內容</p>
516	        </section>
517	      );
518	    }
519	
520	    return (
521	      <section className="h-[214px] bg-[rgba(6,45,65,0.1)] pt-[13px] pb-1 pl-[44px] rounded-[12px] flex flex-col justify-between">
522	        <video
523	          ref={videoRef}
524	          src={videoSrc || undefined}
525	          className="hidden"
526	          playsInline
527	          crossOrigin="anonymous"
528	          onLoadedMetadata={handleLoadedMetadata}
529	          onError={() => setVideoLoadFailed(true)}
530	          onPlay={() => setIsPlaying(true)}
531	          onPause={() => setIsPlaying(false)}
532	          onEnded={() => setIsPlaying(false)}
533	        />
534	
535	        <div
536	          ref={keyframeStripRef}
537	          className="w-full overflow-x-hidden overflow-y-visible flex-1 flex flex-col justify-start"
538	          style={{
539	            paddingLeft: yAxisGutterPx, // 對齊 EngagementChart 的 Y 軸
540	            boxSizing: "border-box",
541	            maxWidth: "100%",
542	          }}
543	        >
544	          <div
545	            className="flex flex-col overflow-x-auto overflow-y-visible min-w-0 scroll-smooth 
546	                      [&::-webkit-scrollbar]:hidden [scrollbar-width:none]"
547	            style={{
548	              width: `${totalChartWidth + RIGHT_MARGIN}px`,
549	            }}
550	          >
551	            <div
552	              className="h-[132px] flex items-center mb-2.5 ml-[8px] cursor-pointer touch-none select-none"
553	              style={{
554	                width: `${totalChartWidth}px`,
555	                boxSizing: "border-box",
556	              }}
557	              onPointerDown={onKeyframePointerDown}
558	            >
559	              {showPlaceholderStrip &&
560	                placeholderTiles.map((color, i) => {
561	                  const isActive = i === activePlaceholderIndex;
562	
563	                  return (
564	                    <div
565	                      key={i}
566	                      data-kf-index={i}
567	                      style={{
568	                        width: `${isActive ? activeThumbWidthPx : placeholderTileWidthPx}px`,
569	                        flexShrink: 0,
570	                      }}
571	                      className={`relative h-[132px] overflow-hidden box-border pointer-events-none ${color} ${
572	                        isActive
573	                          ? "border-[2px] border-inset border-gray-40 z-10"
574	                          : "border-none"
575	                      }`}
576	                    />
577	                  );
578	                })}
579	
580	              {thumbnails.map((src, i) => {
581	                const isActive = i === activeThumbIndex;
582	                const currentWidth = isActive
583	                  ? activeThumbWidthPx
584	                  : nonActiveThumbWidthPx;
585	
586	                return (
587	                  <div
588	                    key={i}
589	                    data-kf-index={i}
590	                    style={{
591	                      width: `${currentWidth}px`,
592	                      flexShrink: 0,
593	                    }}
594	                    className={`relative h-[132px] overflow-hidden box-border pointer-events-none ${
595	                      isActive
596	                        ? "border-[2px] border-inset border-gray-40 z-10"
597	                        : "border-none"
598	                    }`}
599	                  >
600	                    <img
601	                      src={src}
602	                      alt={`thumb-${i}`}
603	                      style={{ width: "100%" }}
604	                      className="absolute left-0 top-0 h-full object-cover object-left max-w-none"
605	                      draggable={false}
606	                    />
607	                  </div>
608	                );
609	              })}
610	            </div>
611	
612	            {/* 影片 Playbar*/}
613	            <div
614	              className="relative mb-2 ml-[8px] z-30 overflow-visible"
615	              style={{
616	                width: `${totalChartWidth}px`,
617	                boxSizing: "border-box",
618	              }}
619	            >
620	              <div
621	                ref={progressBarRef}
